157:void
158:Coin::collect()
159:{
160:  static Timer sound_timer;
161:  static int pitch_one = 128;
162:  static float last_pitch = 1;
163:  float pitch = 1;
164:
165:  int tile = static_cast<int>(get_pos().y / 32);
166:
167:  if (!is_valid())
168:    return;
169:
170:  if (!sound_timer.started()) {
171:    pitch_one = tile;
172:    pitch = 1;
173:    last_pitch = 1;
174:  } else if (sound_timer.get_timegone() < 0.02f) {
175:    pitch = last_pitch;
176:  } else {
177:    switch ((pitch_one - tile) % 7) {
178:      case -6:
179:        pitch = 1.f/2;  // C.
180:        break;
181:      case -5:
182:        pitch = 5.f/8;  // E.
183:        break;
184:      case -4:
185:        pitch = 4.f/6;  // F.
186:        break;
187:      case -3:
188:        pitch = 3.f/4;  // G.
189:        break;
190:      case -2:
191:        pitch = 5.f/6;  // A.
192:        break;
193:      case -1:
194:        pitch = 9.f/10;  // Bb.
195:        break;
196:      case 0:
197:        pitch = 1.f;  // c.
198:        break;
199:      case 1:
200:        pitch = 9.f/8;  // d.
201:        break;
202:      case 2:
203:        pitch = 5.f/4;  // e.
204:        break;
205:      case 3:
206:        pitch = 4.f/3;  // f.
207:        break;
208:      case 4:
209:        pitch = 3.f/2;  // g.
210:        break;
211:      case 5:
212:        pitch = 5.f/3;  // a.
213:        break;
214:      case 6:
215:        pitch = 9.f/5;  // bb.
216:        break;
217:    }
218:    last_pitch = pitch;
219:  }
220:  sound_timer.start(1);
221:
222:  std::unique_ptr<SoundSource> soundSource = SoundManager::current()->create_sound_source("sounds/coin.wav");
223:  soundSource->set_position(get_pos());
224:  soundSource->set_pitch(pitch);
225:  soundSource->play();
226:  SoundManager::current()->manage_source(std::move(soundSource));
227:
228:  Sector::get().get_players()[0]->get_status().add_coins(1, false);
229:  Sector::get().add<BouncyCoin>(get_pos(), false, get_sprite_name());
230:  if (m_count_stats && !m_parent_dispenser)
231:    Sector::get().get_level().m_stats.increment_coins();
232:  remove_me();
233:
234:  if (!m_collect_script.empty()) {
235:    Sector::get().run_script(m_collect_script, "collect-script");
236:  }
237:}
