#include "object/coin_explode.hpp"

#include "math/random.hpp"
#include "object/coin.hpp"
#include "supertux/sector.hpp"

#include <array>

CoinExplode::CoinExplode(const Vector& pos, bool count_stats, const std::string& sprite) :
  m_sprite(sprite),
  position(pos),
  m_count_stats(count_stats)
{
}

void
CoinExplode::update(float )
{
  float mag = 100.0f; // Magnitude at which coins are thrown.
  float rand = 30.0f; // Max variation to be subtracted from the magnitude.

  // Each coin in the explosion has a different velocity. Only one half of
  // the fan is listed; every entry is thrown twice, once mirrored.
  static const std::array<Vector, 5> coin_velocities = {{
    { 2.5f, -4.5f }, { 2.f, -5.f },
    { 1.5f, -5.5f }, { 1.f, -6.f }, { 0.5f, -6.5f }
  }};

  for (const auto& vector : coin_velocities)
  {
    for (const float side : { 1.f, -1.f })
    {
      const Vector velocity = Vector(vector.x, vector.y * side) * (mag - gameRandom.randf(rand));
      Sector::get().add<HeavyCoin>(position, velocity, m_count_stats, m_sprite);
    }
  }

  remove_me();
}

void
CoinExplode::draw(DrawingContext &)
{
}
  const bool m_count_stats;

private:
  Coin(const Coin&) = delete;
  Coin& operator=(const Coin&) = delete;
};

class HeavyCoin final : public Coin
{
public:
  HeavyCoin(const Vector& pos, const Vector& init_velocity, bool count_stats = true,
            const std::string& sprite_path = "images/objects/coin/coin.sprite");
  HeavyCoin(const ReaderMapping& reader, bool count_stats = true);

  virtual void update(float dt_sec) override;
  virtual void collision_solid(const CollisionHit& hit) override;

  static std::string class_name() { return "heavycoin"; }
  virtual std::string get_class_name() const override { return class_name(); }
  static std::string display_name() { return _("Heavy Coin"); }
  virtual std::string get_display_name() const override { return display_name(); }
  virtual GameObjectClasses get_class_types() const override { return Coin::get_class_types().add(typeid(HeavyCoin)); }

  virtual ObjectSettings get_settings() override;
  virtual void after_editor_set() override;

  virtual void on_flip(float height) override;

private:
  Physic m_physic;
  CollisionHit m_last_hit;

private:
  HeavyCoin(const HeavyCoin&) = delete;
  HeavyCoin& operator=(const HeavyCoin&) = delete;
};
